using System.ClientModel;
using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

// ---------------------------------------------------------------------------
// Tools – web search & note-taking
// ---------------------------------------------------------------------------
var researchNotes = new ResearchNotes();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
            WebSearchTool.SearchAsync(query),
        "web_search",
        "Search the web for information on a topic. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("URL to fetch and read")] string url) =>
            WebSearchTool.FetchPageAsync(url),
        "read_page",
        "Fetch a web page and return its text content (truncated to a reasonable length)."),

    AIFunctionFactory.Create(
        ([Description("Title or heading for the note")] string title,
         [Description("The note content")] string content) =>
            researchNotes.AddNote(title, content),
        "save_note",
        "Save a research note for later reference. Use this to record important findings."),

    AIFunctionFactory.Create(
        () => researchNotes.GetAllNotes(),
        "get_notes",
        "Retrieve all research notes saved so far."),
};

// ---------------------------------------------------------------------------
// Build the chat client with automatic function-calling
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(modelName)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║         AI Research Agent                ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();
Console.WriteLine("Enter a research topic (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    researchNotes.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. Given a topic, you:
            1. Search the web for relevant information (2-3 searches with varied queries).
            2. Read the most promising pages to gather details.
            3. Save important findings as notes using the save_note tool.
            4. After collecting enough information, retrieve your notes and write a
               well-structured summary with key facts, organized under clear headings.
            Be thorough but concise. Cite sources where possible.
            """),
        new(ChatRole.User, $"Research the following topic and provide a summary:\n\n{topic}"),
    };

    Console.WriteLine($"\nResearching \"{topic}\"...\n");

    try
    {
        var response = await client.GetResponseAsync(messages, chatOptions);

        Console.WriteLine("── Research Summary ─────────────────────────");
        Console.WriteLine(response.Text);
        Console.WriteLine("─────────────────────────────────────────────\n");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
    }
}

Console.WriteLine("Goodbye!");

