static partial class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" },
            { "Accept", "text/html" },
        },
    };

    /// <summary>
    /// Performs a web search using DuckDuckGo's HTML interface and returns
    /// result snippets.
    /// </summary>
    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var results = new List<string>();
            // Extract result titles and snippets from DuckDuckGo HTML results
            var linkMatches = ResultLinkRegex().Matches(html);
            var snippetMatches = SnippetRegex().Matches(html);

            for (var i = 0; i < Math.Min(linkMatches.Count, 5); i++)
            {
                var title = StripHtml(linkMatches[i].Groups[1].Value);
                var href = WebUtility.UrlDecode(
                    linkMatches[i].Groups[0].Value
                        .Split("uddg=", 2).ElementAtOrDefault(1)?.Split('&')[0] ?? "");
                var snippet = i < snippetMatches.Count
                    ? StripHtml(snippetMatches[i].Groups[1].Value)
                    : "";
                results.Add($"[{i + 1}] {title}\n    URL: {href}\n    {snippet}");
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : "No results found.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    /// <summary>Fetches a page and returns its text content.</summary>
    public static async Task<string> FetchPageAsync(string url)
    {
        try
        {
            var html = await Http.GetStringAsync(url);

            // Strip scripts, styles, then all tags
            html = ScriptStyleRegex().Replace(html, " ");
            html = TagRegex().Replace(html, " ");
            html = WebUtility.HtmlDecode(html);
            html = WhitespaceRegex().Replace(html, " ").Trim();

            const int maxLength = 8_000;
            if (html.Length > maxLength)
                html = html[..maxLength] + "\n...[truncated]";

            return html;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static string StripHtml(string html)
    {
        var text = TagRegex().Replace(html, "");
        return WebUtility.HtmlDecode(text).Trim();
    }

    [GeneratedRegex(@"<a[^>]+class=""result__a""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex ResultLinkRegex();

    [GeneratedRegex(@"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex(@"<(script|style)[^>]*>.*?</\1>", RegexOptions.Singleline | RegexOptions.IgnoreCase)]
    private static partial Regex ScriptStyleRegex();

    [GeneratedRegex(@"<[^>]+>")]
    private static partial Regex TagRegex();

    [GeneratedRegex(@"\s+")]
    private static partial Regex WhitespaceRegex();
}

// ===========================================================================
// Note-Taking Tool
// ===========================================================================
class ResearchNotes
{
    private readonly List<(string Title, string Content)> _notes = [];

    public string AddNote(string title, string content)
    {
        _notes.Add((title, content));
        return $"Note saved: \"{title}\" ({_notes.Count} total notes)";
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"## Note {i + 1}: {_notes[i].Title}");
            sb.AppendLine(_notes[i].Content);
            sb.AppendLine();
        }
        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

